struct RelocationEntry {
    // Offset relative to the start of the section/segment
    uint64_t r_offset;

    // Defines the type of fixup needed (e.g., PC-relative, Absolute)
    uint64_t r_info;

    // Optional constant value added to the calculated address
    int64_t  r_addend;
};

// Example fixup needed 0x2A bytes into the .text section
RelocationEntry fixup = {
    .r_offset = 0x0000002A,
    .r_info   = 0x050000000A,
    .r_addend = -4
};
